const baseUrl = process.env.REACT_APP_TEXT_API_BASE_URL + '/text/board';

export async function fetchBoard(length = 16, boardId) {
  let url = baseUrl;
  if (typeof(boardId) !== 'undefined' && boardId != null) {
    url += '/' + boardId;
  }
  url += '?' + length;

  console.log("About to fetch board.")

  let fetchresult = await fetch(url)
  .then(res => { console.log(res); return res;})
    .then(res => res.json())
    .then(
      (result) => {
        console.log("Got board: {}", result);
        return result;
      },
      (error) => { console.log("Error: ", error); }
    );
  console.log("Fetch result: ", fetchresult);
  return fetchresult;
}

export default fetchBoard;