import React from 'react';
import './App.css';
import Board from './Board.jsx';
import BoggleTimer from './BoggleTimer.jsx';
import WordEntry from './WordEntry.jsx';
import WordTracker from './WordTracker.jsx';
import { useTimer } from "react-timer-hook";

function nowPlusTime(seconds) {
  const d = new Date();
  d.setSeconds(d.getSeconds() + seconds);
  return d;
}

function SessionGame(props) {
  const { reroll, haveIStartedEver, wordList, boardState, submitWord } = props;

  const {
    seconds,
    minutes,
    pause,
    restart,
    isRunning
  } = useTimer({ expiryTimestamp: nowPlusTime(70), onExpire: () => console.warn('onExpire called') });
  
  return (
    <section className="game">
      <BoggleTimer reroll={undefined} seconds={seconds} minutes={minutes} haveIStartedEver={haveIStartedEver} />
      <WordTracker wordList={wordList} />

      <Board rows="4" cols="4"
        boardState={boardState} />

      <WordEntry submitWord={submitWord} enabled={isRunning} />
    </section>
  );
}

export default SessionGame;
