import React from 'react';
import './App.css';
import Board from './Board.jsx';
import BoggleTimer from './BoggleTimer.jsx';
import WordEntry from './WordEntry.jsx';
import WordTracker from './WordTracker.jsx';

function SinglePlayerGame(props) {
  const { reroll, seconds, minutes, haveIStartedEver, wordList, boardState, submitWord, isRunning } = props;

  return (
    <section className="game">
      <BoggleTimer reroll={reroll} seconds={seconds} minutes={minutes} haveIStartedEver={haveIStartedEver} />
      <WordTracker wordList={wordList} />

      <Board rows="4" cols="4"
        boardState={boardState} />

      <WordEntry submitWord={submitWord} enabled={isRunning} />
    </section>
  );
}

export default SinglePlayerGame;
