import React, { useState } from 'react';
import './App.css';
import SessionBrowser from './SessionBrowser.jsx';
import SinglePlayerGame from './SinglePlayerGame.jsx';
import useBoardState from './useBoardState.js';
import randomHiragana from './StochasticRandomHiragana.jsx';
import { fetchSessions, createSession, joinSession } from './client/sessionClient.jsx';
import { fetchBoard } from './client/boardClient.jsx';
import SessionGame from './SessionGame';

function App() {

  const {
    reroll,
    boardState,
    setBoardState,
    haveIStartedEver,
    seconds,
    minutes,
    wordList,
    submitWord,
    isRunning,
    restart
  } = useBoardState(randomHiragana, true, 70);

  const [sessionList, setSessionList] = useState([]);
  const [appState, setAppState] = useState(undefined);

  function interior() {
    if (appState === 'singlePlayer') {
      return (<SinglePlayerGame reroll={reroll} seconds={seconds} minutes={minutes}
        haveIStartedEver={haveIStartedEver} wordList={wordList} boardState={boardState}
        submitWord={submitWord} isRunning={isRunning}/>);
    } else if (appState === 'session') {
      async function myFetchSessions() {
        // fetch the list of current sessions
        console.log("Fetching current sessions.");
        const result = await fetchSessions();
        setSessionList(result);
      }

      async function myCreateSession() {
        const result = await createSession(4);
        await myFetchSessions();
        return result;
      }
    
      async function myJoinSession(sessId) {
        // join the session in question
        console.log("Joining session {}", sessId);

        const result = await joinSession(sessId);

        if (result && result.successfullyJoined && result._links) {
          console.log("Gotta go to this link now: ", result._links.board);
          const boardLink = result._links.board.href;

          const boardId = boardLink.substring(boardLink.lastIndexOf('text/board/') + 11, boardLink.lastIndexOf('?'));
          
          const boardResult = await fetchBoard(16, boardId);
          setBoardState(boardResult.content.split(""));
          setAppState('sessionGame');
          restart(); // restart the timer
        }
      }

      return <SessionBrowser reroll={reroll} seconds={seconds} minutes={minutes}
        haveIStartedEver={haveIStartedEver} wordList={wordList} boardState={boardState}
        submitWord={submitWord} isRunning={isRunning} sessionList={sessionList}
        fetchSessions={myFetchSessions} joinSession={myJoinSession} createSession={myCreateSession}/>
    } else if (appState === 'sessionGame') {
      return <SessionGame seconds={seconds} minutes={minutes}
        haveIStartedEver={haveIStartedEver} wordList={wordList} boardState={boardState}
        submitWord={submitWord} isRunning={isRunning}/>;
    } else {
      return (
        <section className="selectGameType">
          <button onClick={() => { setAppState('singlePlayer');} }>Single Player</button>
          <button onClick={() => { setAppState('session');} }>Session</button>
        </section>
        );
    }
  }

  document.title = 'Hiragana Boggle';

  return (
    <div className="App">
      { interior() }
    </div>
  );
}

export default App;
