import React from 'react';
import { useEffect } from 'react';
import './SessionBrowser.css';


function SessionBrowser(props) {
  const {reroll, seconds, minutes, haveIStartedEver, wordList, boardState, submitWord, isRunning,
    sessionList, fetchSessions, joinSession, createSession} = props;

    useEffect(() => {
      fetchSessions();
    }, []);

  return (
    <section className="sessionBrowser">
      <div className="sessionList">Session list
        <ul>{sessionList.map((session) =>
          <li key={session.sessionId} onClick={() => joinSession(session.sessionId)}>Joiners/Cap: {session.currentJoiners} / {session.cap}</li>
        )}</ul>
      </div>
      <button className="refresh" onClick={() => fetchSessions()}>Refresh</button>
      <button className="create" onClick={() => createSession()}>Create</button>
    </section>
  )
}

export default SessionBrowser;