import React from 'react';

function BoggleTimer({ reroll, minutes, seconds, haveIStartedEver }) {

  return (
    <div className="timer">
        <div className="timerDisplay">
          <span>{minutes}</span>:<span>{seconds.toString().padStart(2, '0')}</span>
        </div>
        { typeof(reroll) === 'function' &&
          <button className="timerButton" onClick={() => {
          reroll();
          }}>{haveIStartedEver ? 'Restart' : 'Start'}</button>
        }
    </div>
  );
}

export default BoggleTimer;
