const baseUrl = process.env.REACT_APP_TEXT_API_BASE_URL + '/sessions';

export async function fetchSessions() {
  let url = baseUrl;

  console.log("About to fetch sessions.")

  let fetchresult = await fetch(url)
  .then(res => { console.log(res); return res;})
    .then(res => res.json())
    .then(
      (result) => {
        console.log("Got sessions: {}", result);
        return result.sessions;
      },
      (error) => { console.log("Error: ", error); return error; }
    );
  console.log("Fetch result: ", fetchresult);
  return fetchresult;
};

export async function createSession(cap) {
  let url = baseUrl;

  console.log("About to create a session.");

  let fetchresult = await fetch(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({cap: cap})
  })
  .then(res => { console.log(res); return res;})
    .then(res => res.json())
    .then(
      (result) => {
        console.log("Created session: {}", result);
        return result;
      },
      (error) => { console.log("Error: ", error); return error; }
    );
  console.log("Fetch result: ", fetchresult);
  return fetchresult;
}

export async function joinSession(sessionId) {
  let url = baseUrl + '/' + sessionId + '/join';

  console.log("About to join a session.");

  let fetchresult = await fetch(url, {
    method: 'PUT',
  })
  .then(res => { console.log(res); return res;})
    .then(res => res.json())
    .then(
      (result) => {
        console.log(" join result: {}", result);
        return result;
      },
      (error) => { console.log("Error: ", error); return error; }
    );
  console.log("Fetch result: ", fetchresult);
  return fetchresult;
}

export default fetchSessions;