import { useEffect, useState } from "react";
import { useTimer } from "react-timer-hook";
import fetchBoard from "./client/boardClient.jsx";

function nowPlusTime(seconds) {
  const d = new Date();
  d.setSeconds(d.getSeconds() + seconds);
  return d;
}

function generateBoardState(populator) {
  return new Array(16).fill(0).map(populator);
}  

function useBoardState(populator, supportReroll, time) {

  const {
    seconds,
    minutes,
    pause,
    restart,
    isRunning
  } = useTimer({ expiryTimestamp: nowPlusTime(time), onExpire: () => console.warn('onExpire called') });

  useEffect(() => {
    pause();
    //eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const [haveIStartedEver, setHaveIStartedEver] = useState(false);
  const [boardState, setBoardState] = useState("abcdefghijklmnop".split(""));
  const [wordList, setWordList] = useState([]);

  function reroll() {
    setWordList([]);
    setHaveIStartedEver(true);

    if (supportReroll && typeof(populator) === 'function' ) {
      setBoardState(generateBoardState(populator));
    } else {
      let result = fetchBoard(16, 'blarg')
      .then(
        res => {
          console.log(res);
          setBoardState(res.content.split(""));
        }
      );
      console.log(result);
    }
    
    restart(nowPlusTime(time));
  }

  function handleRForReroll(e) {
    if (e.code === "KeyR" && e.target.type !== "text") {
      reroll();
    }
  }

  useEffect(() => {
    if (supportReroll) {
      window.addEventListener("keydown", handleRForReroll);
      return () => {
        window.removeEventListener("keydown", handleRForReroll);
      }
    }
      //eslint-disable-next-line react-hooks/exhaustive-deps
  }, [time]);

  function submitWord(word) {
    setWordList([...wordList, word]);
  }

  return {
    reroll,
    submitWord,
    wordList,
    boardState,
    setBoardState,
    haveIStartedEver,
    seconds,
    minutes,
    isRunning,
    restart
  };
};

export default useBoardState;