import React from 'react';

function WordEntry({ submitWord, enabled }) {

  function handleKeyDown(e) {
    if (e.key === "Enter") {
      e.preventDefault();
      submitWord(e.target.value);
      e.target.value = '';
    }
  }

  return (
    <div className="wordEntry">
      <input id="wordEntryField" type="text" onKeyDown={handleKeyDown} disabled={!enabled} value={!enabled ? "" : null}/>
    </div>
  )
}

export default WordEntry;